    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the remaining space after placing the item
    let mut score = post_residual as f64;

    // 1. Lookahead: favor residuals that can accommodate the next item
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // Residual too small for next item – penalise
            score += diff as f64 * 0.4;
        } else {
            // Residual large enough – reward closeness
            score -= (-diff) as f64 * 0.4;
        }
    }

    // 2. Balance against the mean residual across open bins
    let delta_mean = post_residual as f64 - mean_residual;
    score += delta_mean.abs() * 0.1;

    // 3. If this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 4. New‑bin candidate: penalise opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        // New empty bin
        score -= (open_bins_count as f64) * 5.0;
    }

    // 5. Slightly favour bins that leave very little residual (encourage compact packing)
    score -= (post_residual as f64).sqrt() * 0.05;

    // 6. Stage adjustment: in the early part of the stream be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 0.2 * (post_residual as f64);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: smaller residual → lower score
    let mut score = post_residual as f64;

    // Dead‑space penalty: if the next item cannot fit, heavily penalize
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1000.0 - post_residual as f64;
    } else {
        // Small gap penalty for any remaining space
        score += post_residual as f64 * 0.2;
    }

    // Open‑bins pressure: encourage tighter packing when many bins are open
    score += (open_bins_count as f64) * post_residual as f64 * 0.01;

    // Mean residual adjustment: reward bins better than average
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Fitting‑bins count: reward the last possible bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New‑bin candidate: penalize opening a bin that would leave large dead space
    if bin_residual == bin_capacity {
        let new_post = bin_capacity - item_size;
        score += new_post as f64 * 0.2;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the more residual left, the higher the score
    let mut score = post_residual as f64;

    // If this is the only bin that can accept the item, give it a huge bonus
    if fitting_bins_count == 1 {
        score -= 1_000.0;
    }

    // Aggressive 2‑step lookahead: compare residual after this placement to the next item
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Enough space for the next item – reward
            score -= 0.5 * diff as f64;
        } else {
            // Not enough space – penalize
            score += 10.0 * (-diff as f64);
        }
    }

    // Align residual with the mean of all open bins
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * mean_diff;

    // Prefer bins that are already dense (small residual left)
    score += 0.05 * (bin_capacity - post_residual) as f64;

    // As the stream progresses, favor using existing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress;

    // New‑bin candidate gets a small penalty to discourage opening unless necessary
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    _step_index: usize,
    _total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the smaller the residual after placement, the better.
    let mut score = post_residual as f64;

    // 1. Strict dead‑space avoidance: penalise if the remaining space
    //    cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64;
    }

    // 2. Penalise very small residuals (<=10) which are likely unusable.
    if post_residual < 10 {
        score += 5.0 * (10 - post_residual) as f64;
    }

    // 3. Pressure from open bins: more open bins increase cost.
    score += 0.5 * (open_bins_count as f64);

    // 4. New‑bin candidate penalty: opening a new bin is costly
    //    unless the item is large (good to start a fresh bin).
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size > 70 {
            score -= 5.0; // reward large items in new bins
        }
    }

    // 5. Reward the bin that is the *only* fit for the item.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // 6. Compare the bin’s residual with the mean residual of all open bins.
    //    Prefer bins that leave a residual larger than average (more fillable).
    if post_residual as f64 > mean_residual {
        score -= 0.1 * (post_residual as f64 - mean_residual);
    } else {
        score += 0.1 * (mean_residual - post_residual as f64);
    }

    score
}

