    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual after packing
    let mut score = post_residual as f64;

    // 1. Strict dead‑space avoidance: tiny gaps are heavily penalised
    if post_residual <= 5 {
        score += 1_000.0;
    }

    // 2. Future‑fit penalty: if the next item won’t fit after this placement
    if next_item_size > 0 && post_residual < next_item_size {
        score += 500.0;
    }

    // 3. Open‑bins pressure: more open bins raise the score of existing bins
    score += (open_bins_count as f64) * 10.0;

    // 4. Unique fitting bin reward: if this is the only bin that can accept the item
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. Mean residual influence: tighter overall bins are rewarded
    if mean_residual < 10.0 {
        score += (10.0 - mean_residual) * 5.0;
    } else {
        score -= (mean_residual - 10.0) * 2.0;
    }

    // 6. Progress factor: earlier in the stream penalise opening new bins
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (1.0 - progress) * 0.1;

    // 7. New‑bin candidate penalty: discourage opening a new bin when there are open ones
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 200.0;
    }

    score
}

