pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item.
    let mut score = post_residual as f64;

    // Increase the penalty for leftover space as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    let residual_weight = 1.0 + progress;
    score *= residual_weight;

    // Prefer bins whose residual is close to the global mean residual.
    let mean_delta = (post_residual as f64 - mean_residual).abs();
    score -= mean_delta * 0.1;

    // Look‑ahead: penalise bins that would leave space too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        }
    }

    // Fitting bin count: strongly favour the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Open bins count: if many bins are open, prefer to use the one with less residual.
    if open_bins_count > 1 {
        score += (open_bins_count as f64) * 0.2;
    }

    // Handle the candidate for a brand new bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is normally penalised.
        score += 10.0;
        // But if no existing bin can fit, reward opening a new one.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    score
}
